import { useId } from 'react';
import './NavigationSidebar.css';
export function NavigationSidebar({ selected, onNavigate, onHelp, onSettings }: { selected: string; onNavigate: (id: string) => void; onHelp: () => void; onSettings: () => void }) {
  const id = useId();
  const sections = [
    { name: 'Workspace', rows: [{ id: 'overview', label: 'Overview', icon: '▦' }, { id: 'projects', label: 'Projects' }] },
    { name: 'Team', rows: [{ id: 'members', label: 'Members', icon: '♧' }, { id: 'reports', label: 'Reports', disabled: true }] }
  ];
  return <aside className="navigation-sidebar"><nav aria-label="Workspace navigation">{sections.map((section, index) => <section key={section.name} aria-labelledby={id + index}><h2 id={id + index}>{section.name}</h2><ul>{section.rows.map(row => <li key={row.id}><button type="button" disabled={'disabled' in row && row.disabled} aria-current={selected === row.id ? 'page' : undefined} onClick={() => onNavigate(row.id)}><span className="nav-icon" aria-hidden="true">{'icon' in row ? row.icon : null}</span><span>{row.label}{'disabled' in row && row.disabled ? ' (unavailable)' : ''}</span></button></li>)}</ul></section>)}</nav><section className="workspace-summary" aria-label="Workspace summary"><strong>Design workspace</strong><p>12 projects · 8 members</p></section><footer><button type="button" onClick={onHelp}>Help</button><button type="button" onClick={onSettings}>Settings</button></footer></aside>;
}

