.navigation-sidebar { --row-padding: .65rem; display: flex; flex-direction: column; gap: 1rem; padding: 1rem; width: min(100%, 18rem); min-height: 0; overflow: auto; color: #20232a; background: #f4f5f7; box-sizing: border-box; }
.navigation-sidebar nav { display: grid; gap: 1.25rem; }
.navigation-sidebar h2 { font-size: .8rem; margin: 0 0 .4rem; padding-inline: var(--row-padding); }
.navigation-sidebar ul { list-style: none; padding: 0; margin: 0; }
.navigation-sidebar li button { display: grid; grid-template-columns: 1.1rem minmax(0, 1fr); align-items: center; gap: .5rem; width: 100%; text-align: left; padding: var(--row-padding); border: 1px solid transparent; background: transparent; border-radius: .35rem; overflow-wrap: anywhere; }
.navigation-sidebar button { font: inherit; color: inherit; cursor: pointer; }
.navigation-sidebar button[aria-current] { background: #e0e8fa; border-color: #4064a5; font-weight: 700; }
.navigation-sidebar button:disabled { color: #676b73; cursor: default; }
.navigation-sidebar button:focus-visible { outline: 3px solid #205ed8; outline-offset: 2px; }
.workspace-summary { padding: var(--row-padding); border: 1px solid #bac1cc; border-radius: .35rem; background: white; }
.workspace-summary p { font-size: .85rem; margin: .4rem 0 0; }
.navigation-sidebar footer { margin-top: auto; display: flex; gap: .5rem; flex-wrap: wrap; }
.navigation-sidebar footer button { padding: .4rem var(--row-padding); }
